"use client";

import { Link2, Volume2, VolumeX } from "lucide-react";
import { useEffect, useState, useSyncExternalStore } from "react";

import { Button } from "@/components/ui/button";
import { toast } from "@/components/ui/toast";

/**
 * Copy the link, and listen. Listening uses the browser's own speech engine
 * (no audio leaves the device, nothing is generated by a model); where the
 * browser has none, the button is not shown.
 */
export function ReaderTools({ text }: { text: string }) {
  const [speaking, setSpeaking] = useState(false);
  // Whether the browser can speak: known only in the browser, so the server renders without the button.
  const canSpeak = useSyncExternalStore(
    () => () => undefined,
    () => "speechSynthesis" in window,
    () => false,
  );
  useEffect(
    () => () => {
      if ("speechSynthesis" in window) window.speechSynthesis.cancel();
    },
    [],
  );

  async function copy() {
    try {
      await navigator.clipboard.writeText(window.location.href);
      toast.success("Link copied.");
    } catch {
      toast.error("Could not copy. Copy the address from the address bar instead.");
    }
  }

  function listen() {
    const synth = window.speechSynthesis;
    if (speaking) {
      synth.cancel();
      setSpeaking(false);
      return;
    }
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = "en-IN";
    utterance.onend = () => setSpeaking(false);
    utterance.onerror = () => setSpeaking(false);
    synth.speak(utterance);
    setSpeaking(true);
  }

  return (
    <div className="flex flex-wrap items-center gap-1">
      <Button variant="ghost" size="sm" onClick={() => void copy()}>
        <Link2 className="size-4" aria-hidden /> Copy link
      </Button>
      {canSpeak ? (
        <Button variant="ghost" size="sm" onClick={listen} aria-pressed={speaking}>
          {speaking ? <VolumeX className="size-4" aria-hidden /> : <Volume2 className="size-4" aria-hidden />}
          {speaking ? "Stop" : "Listen"}
        </Button>
      ) : null}
    </div>
  );
}
